#include <vector>
#include <iostream>

int main() {
    std::vector<int> v;
    v.reserve(100); 
    std::cout << "Capacity after reserve(100): " << v.capacity() << std::endl;

    // Attempt to shrink capacity (N=10 < 100)
    v.reserve(10); 

    // Output shows capacity remains 100 (or greater, depending on implementation)
    std::cout << "Capacity after reserve(10): " << v.capacity() << std::endl;

    // Correct way to request capacity reduction (C++11)
    // v.shrink_to_fit(); 
}
